import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.RQXGjTIX.js";const _=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),r={name:"guide/changelog.md"};function t(d,e,n,s,c,h){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="_0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#_0-2-1" aria-label="Permalink to &quot;0.2.1&quot;">​</a></h2><ul><li><strong>JEI 拖拽标记</strong>：安装 JEI 时，把 CCB 的气体 ingredient 或气体虚拟物品拖到配置槽即可标记该槽气体；</li><li>配置槽右键标记现在也支持 CCB 的虚拟气体物品（<code>VirtualGasItems</code>）；</li><li>JEI 是可选依赖，未安装时其余功能不受影响。</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="me-气体接口重做" tabindex="-1">ME 气体接口重做 <a class="header-anchor" href="#me-气体接口重做" aria-label="Permalink to &quot;ME 气体接口重做&quot;">​</a></h3><ul><li>改为与原版 ME 接口相同的<strong>九组配置槽 + 九组缓存槽</strong>结构； 每槽目标数量 0–64kGU，目标压力 0–16 atm（容器额定 24 atm）； 槽位体积按 <code>目标数量 / 目标压力</code> 推导，装满时压力恰好等于目标压力。</li><li>默认<strong>全部双向</strong>；新增<strong>逐槽控制卡</strong>，安装后每槽可独立选择输入 / 输出 / 双向 / 关闭； 移除卡片后回到统一双向，配置保留。</li><li>升级槽从 4 个增加到 <strong>6 个</strong>（速度卡 ≤4、逐槽控制卡 1、安全阀卡 1）。</li><li>新增<strong>安全阀卡</strong>：压力达到 20 atm 时通过 CCB 的 <code>GasReleaseService</code> 真实释放气体 （径向 <code>OVERFLOW</code>，含环境效果/实体推动），只有释放成功才扣除槽内气体。</li><li>气体标记：新增 <code>gas_sample</code> 气体样本物品与 <code>gas_id</code> 数据组件； 支持手持气体样本/气体容器右键配置槽标记；配置槽也接受 AE2 包裹气体物品。</li><li>旧版 8 kL 缓冲罐中的气体在升级时自动转入<strong>第一个空槽</strong>；九槽都满时记录日志并丢弃。</li><li>移除 0.1.x 给 <code>ae2:interface</code> 添加的气体缓存兼容：原版 ME 接口不再从 CCB 管道接收/提供气体， 气体请走本接口、输入/输出总线或存储总线。</li><li>废弃 <code>gas_interface.bufferVolumeLiters</code> / <code>supplyPressureKpa</code> / <code>transferRate</code> / <code>energyPerKiloGasUnit</code> 配置项；仅保留 <code>gas_interface.idlePower</code>。</li></ul><h3 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h3><ul><li>输入/输出总线的逐部件目标压力尚未实现（本期只保证气体标记与数量）；</li><li>JEI 拖拽标记尚未接入（气体样本/容器标记与 AE2 包裹物品可用）；</li><li>气体 P2P、气体存储元件、总线/存储总线/样板供应器的气体支持保持不变。</li></ul><h2 id="_0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#_0-1-1" aria-label="Permalink to &quot;0.1.1&quot;">​</a></h2><ul><li>256×256 模组图标；</li><li>新的气体接口方块贴图；</li><li>0.1.0 的发布修正。</li></ul><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><ul><li>首个版本：气体存储元件（1k–256k）、ME 气体接口、气体 P2P 隧道、 元件升级卡、GuideME 教程。</li></ul>',12)])])}const g=a(r,[["render",t]]);export{_ as __pageData,g as default};
